examples.template:
Column(
    modifier = Modifier.widthIn(max = 416.dp),
    verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space4),
) {
    MonarchAiAutofillField(
        state = state0,
        suggestion = {{fields.0.suggestion}},
        onAccept = { state0 = MonarchAiAutofillState.Accepted },
        onClear = {
            value0 = ""
            state0 = MonarchAiAutofillState.Cleared
        },
        fieldName = {{fields.0.label}}.lowercase(),
        source = {{fields.0.source}},
        confidence = {{fields.0.confidence|double}}f,
        acceptIcon = { MonarchIcon(SampleIcons.Check, contentDescription = null, size = MonarchIconSize.Sm) },
        clearIcon = { MonarchIcon(SampleIcons.Close, contentDescription = null, size = MonarchIconSize.Sm) },
    ) {
        MonarchTextField(
            value = value0,
            onValueChange = {
                value0 = it
                if (state0 != MonarchAiAutofillState.Cleared) state0 = MonarchAiAutofillState.Edited
            },
            label = {{fields.0.label}},
        )
    }
    MonarchAiAutofillField(
        state = state1,
        suggestion = {{fields.1.suggestion}},
